mapper.select:
SELECT task_id, task_type, task_status, user_id, merchant_id, conversation_id, thread_id, current_run_id, lease_token, lease_owner, input_json, next_action, workflow_version, result_json, error_code, error_message, pause_reason, cancel_reason, pause_requested_at, cancel_requested_at FROM ai_task WHERE task_type IN
#{t}
AND ( task_status = 'QUEUED' OR (task_status = 'RUNNING' AND (lease_expires_at IS NULL OR lease_expires_at < CURRENT_TIMESTAMP(3))) ) ORDER BY priority DESC, available_at ASC, id ASC LIMIT 1 FOR UPDATE SKIP LOCKED

mapper.update:
UPDATE ai_task
SET last_heartbeat_at = CURRENT_TIMESTAMP(3),
    lease_expires_at = DATE_ADD(CURRENT_TIMESTAMP(3), INTERVAL #{leaseSeconds} SECOND)
WHERE task_id = #{taskId}
  AND lease_token = #{leaseToken}

UPDATE ai_task
SET pause_requested_at = CURRENT_TIMESTAMP(3),
    pause_reason = #{reason}
WHERE task_id = #{taskId}
